_CORE_SRC = '# Diagnosis:\n# The report shows no losses, so there is no supported seat-specific failure.\n# The champion\'s smallest reported advantage is against marginal greedy play.\n# Two limitations still matter against stronger opposition:\n#   * A drone must follow a shortest path to one fixed destination and then stay.\n#     This excludes collecting a forecast spike, relocating, and returning home.\n#   * The predicted opponent responds to current positions, not our planned moves.\n# Keep exact margin scoring, intermediate upkeep, forecast timing and validation.\n# Improvements: time-expanded best-response paths, and a second opponent response\n# to our proposed deployment. Mix opponent scenarios rather than fractional drones.\n# All search is interruptible between complete, legal coordinate updates.\n\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\n\ndef margin(k, e, demand):\n    denominator = max(5.0 * (k + e), demand)\n    if denominator <= 0.0:\n        return 0.0\n    return 5.0 * (k - e) * demand / denominator\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self.map_key = None\n        self.adj = []\n        self.options = []\n        self.own_memory = []\n        self.enemy_memory = []\n        self.last_turn = None\n        self.last_enemy = None\n        self.last_prediction = None\n        self.pred_error = 2.0\n        self.stay_error = 2.0\n        self.bad_reports = 0\n\n    def _build(self, n, edges):\n        adj = [[] for _ in range(n)]\n        for u, v in edges:\n            if 0 <= u < n and 0 <= v < n and u != v:\n                adj[u].append(v)\n                adj[v].append(u)\n        self.adj = [sorted(set(row)) for row in adj]\n        # Staying wins exact ties, avoiding purposeless motion.\n        self.options = [[v] + self.adj[v] for v in range(n)]\n\n    def _initial_plan(self, have, memory, h, consecutive, base):\n        remaining = list(have)\n        plan = []\n        if consecutive:\n            for s, old_path in memory:\n                if not (0 <= s < len(have)) or remaining[s] <= 0:\n                    continue\n                path = list(old_path[:h])\n                if not path:\n                    path = [s]\n                path.extend([path[-1]] * (h - len(path)))\n                u = s\n                legal = True\n                for v in path:\n                    if v != u and v not in self.adj[u]:\n                        legal = False\n                        break\n                    u = v\n                if legal:\n                    plan.append([s, path])\n                    remaining[s] -= 1\n        # Optimize deployed units first; reserve drones then fill remaining gaps.\n        order = sorted(range(len(have)), key=lambda s: (s == base, s))\n        for s in order:\n            for _ in range(max(0, remaining[s])):\n                plan.append([s, [s] * h])\n        return plan\n\n    @staticmethod\n    def _occupancy(plan, n, h):\n        result = [[0] * n for _ in range(h)]\n        for _, path in plan:\n            for t, v in enumerate(path):\n                result[t][v] += 1\n        return result\n\n    def _utility(self, n, units, base, demands, weights, scenarios):\n        h = len(weights)\n        utility = []\n        for t in range(h):\n            layer = []\n            for v in range(n):\n                d = demands[v][t]\n                upkeep = 0.0 if v == base else 2.0\n                row = []\n                cases = [(prob, positions[t][v])\n                         for prob, positions in scenarios if prob > 0.0]\n                for k in range(units + 1):\n                    value = -upkeep * k\n                    for probability, e in cases:\n                        value += probability * margin(k, e, d)\n                    row.append(weights[t] * value)\n                layer.append(row)\n            utility.append(layer)\n        return utility\n\n    def _optimize(self, plan, utility, weights, deadline, sweeps, deadband):\n        """Exact single-drone best responses on the time-expanded graph."""\n        h = len(weights)\n        n = len(self.adj)\n        occupancy = self._occupancy(plan, n, h)\n        options = self.options\n        move_cost = [0.085 * w for w in weights]\n\n        for _ in range(sweeps):\n            changes = 0\n            for drone in plan:\n                if time.perf_counter() >= deadline:\n                    return occupancy\n                s, old_path = drone\n                for t, v in enumerate(old_path):\n                    occupancy[t][v] -= 1\n\n                gains = []\n                for t in range(h):\n                    layer = []\n                    ut = utility[t]\n                    ot = occupancy[t]\n                    for v in range(n):\n                        k = ot[v]\n                        row = ut[v]\n                        layer.append(row[k + 1] - row[k])\n                    gains.append(layer)\n\n                old_value = 0.0\n                u = s\n                for t, v in enumerate(old_path):\n                    old_value += gains[t][v]\n                    if u != v:\n                        old_value -= move_cost[t]\n                    u = v\n\n                following = [0.0] * n\n                choices = [None] * h\n                for t in range(h - 1, -1, -1):\n                    local = [gains[t][v] + following[v] for v in range(n)]\n                    current = [0.0] * n\n                    choice = [0] * n\n                    penalty = move_cost[t]\n                    for u in range(n):\n                        best_v = u\n                        best = local[u]\n                        for v in options[u][1:]:\n                            value = local[v] - penalty\n                            if value > best + 1e-10:\n                                best = value\n                                best_v = v\n                        current[u] = best\n                        choice[u] = best_v\n                    choices[t] = choice\n                    following = current\n\n                if following[s] > old_value + deadband:\n                    path = []\n                    u = s\n                    for t in range(h):\n                        u = choices[t][u]\n                        path.append(u)\n                    drone[1] = path\n                    changes += 1\n                else:\n                    path = old_path\n\n                for t, v in enumerate(path):\n                    occupancy[t][v] += 1\n            if changes == 0:\n                break\n        return occupancy\n\n    def act(self, obs):\n        start = time.perf_counter()\n        budget = max(0.0001, 0.60 * float(TIME_BUDGET))\n        deadline = start + budget\n\n        n = int(obs.get("n_nodes", 0))\n        have = list(obs.get("player_drones", []))\n        enemy = list(obs.get("opponent_drones", []))\n        forecast = obs.get("demand_forecast", [])\n        if (n <= 0 or len(have) != n or len(enemy) != n\n                or len(forecast) != n):\n            return []\n        base = int(obs.get("player_base", -1))\n        enemy_base = int(obs.get("opponent_base", -1))\n        if not (0 <= base < n and 0 <= enemy_base < n):\n            return []\n        turn = int(obs.get("turn", 0))\n        if turn >= 100 or sum(have) <= 0:\n            return []\n\n        edges = tuple((int(u), int(v)) for u, v in obs.get("edges", []))\n        key = (n, edges, base, enemy_base)\n        if key != self.map_key:\n            self._build(n, edges)\n            self.map_key = key\n            self.own_memory = []\n            self.enemy_memory = []\n            self.last_turn = None\n            self.last_enemy = None\n            self.last_prediction = None\n\n        bad = (not obs.get("action_format_correct_last_turn", True)\n               or int(obs.get("n_invalid_actions_last_turn", 0)) > 0)\n        if bad:\n            self.bad_reports += 1\n\n        consecutive = self.last_turn == turn - 1\n        if consecutive and self.last_prediction is not None:\n            pe = sum(abs(enemy[v] - self.last_prediction[v]) for v in range(n))\n            se = sum(abs(enemy[v] - self.last_enemy[v]) for v in range(n))\n            self.pred_error = 0.8 * self.pred_error + 0.2 * pe\n            self.stay_error = 0.8 * self.stay_error + 0.2 * se\n\n        h = max(1, min(14, 100 - turn))\n        weights = [0.95 ** t for t in range(h)]\n        demands = []\n        for row in forecast:\n            tail_values = row[-3:]\n            tail = sum(tail_values) / len(tail_values) if tail_values else 0.0\n            demands.append([float(row[t]) if t < len(row) else float(tail)\n                            for t in range(h)])\n\n        ours = self._initial_plan(\n            have, self.own_memory, h, consecutive, base)\n        theirs = self._initial_plan(\n            enemy, self.enemy_memory, h, consecutive, enemy_base)\n\n        static_enemy = [list(enemy) for _ in range(h)]\n        initial_own = self._occupancy(ours, n, h)\n\n        # First opponent response: anticipate our continuing deployment rather\n        # than pretending all our drones remain at their observed locations.\n        enemy_utility = self._utility(\n            n, sum(enemy), enemy_base, demands, weights,\n            [(1.0, initial_own)])\n        first_enemy = self._optimize(\n            theirs, enemy_utility, weights,\n            min(deadline, start + budget * 0.22), 2, 0.18)\n\n        # Adapt trust using actual next-turn prediction errors. Even a good model\n        # retains a static scenario, guarding against idle and unusual opponents.\n        confidence = 0.25 + 0.65 * (\n            (self.stay_error + 0.5)\n            / (self.stay_error + self.pred_error + 1.0))\n        utility = self._utility(\n            n, sum(have), base, demands, weights,\n            [(confidence, first_enemy), (1.0 - confidence, static_enemy)])\n        own_positions = self._optimize(\n            ours, utility, weights,\n            min(deadline, start + budget * 0.50), 3, 0.16)\n\n        # A second response exposes nodes the opponent can profitably reinforce\n        # after seeing our deployment. Hedge between both response scenarios:\n        # pure alternating best responses would otherwise oscillate.\n        final_enemy = first_enemy\n        if time.perf_counter() < start + budget * 0.58:\n            enemy_utility = self._utility(\n                n, sum(enemy), enemy_base, demands, weights,\n                [(1.0, own_positions)])\n            final_enemy = self._optimize(\n                theirs, enemy_utility, weights,\n                min(deadline, start + budget * 0.73), 2, 0.18)\n\n        if time.perf_counter() < deadline:\n            utility = self._utility(\n                n, sum(have), base, demands, weights,\n                [(1.0 - confidence, static_enemy),\n                 (0.40 * confidence, first_enemy),\n                 (0.60 * confidence, final_enemy)])\n            self._optimize(ours, utility, weights, deadline, 3, 0.12)\n\n        proposed = {}\n        own_memory = []\n        for s, path in ours:\n            u = path[0]\n            own_memory.append((int(u), path[1:] + [path[-1]]))\n            if u != s:\n                proposed[(s, u)] = proposed.get((s, u), 0) + 1\n\n        # Conservative mode still plays, but uses only individually validated\n        # first edges and discards all warm-start information after bad feedback.\n        if self.bad_reports >= 2:\n            own_memory = []\n            self.enemy_memory = []\n\n        available = list(have)\n        action = []\n        for (s, u), requested in sorted(proposed.items()):\n            if not (0 <= s < n and 0 <= u < n):\n                continue\n            if s == u or u not in self.adj[s]:\n                continue\n            count = min(max(0, int(requested)), max(0, int(available[s])))\n            if count:\n                action.append((int(s), int(u), int(count)))\n                available[s] -= count\n\n        self.own_memory = own_memory\n        if self.bad_reports < 2:\n            self.enemy_memory = [\n                (int(path[0]), path[1:] + [path[-1]])\n                for _, path in theirs\n            ]\n        self.last_turn = turn\n        self.last_enemy = list(enemy)\n        self.last_prediction = [\n            confidence * (0.40 * first_enemy[0][v]\n                          + 0.60 * final_enemy[0][v])\n            + (1.0 - confidence) * enemy[v]\n            for v in range(n)\n        ]\n        return action\n'
